const CIRCUS_FOOT_CENTER = 1;
const _rideFootOff = new THREE.Vector3();
const _rideFootTmpV = new THREE.Vector3(), _rideFootGrp = new THREE.Vector3(), _rideFootTmpQ = new THREE.Quaternion();
